	\IF{$\mathbf{W} \ne \emptyset$}
	\STATE \textbf{Return ID}$(\mathbf{y}, \mathbf{x}\cup \mathbf{w}, P,   G)$
	\ENDIF

	\IF[\textcolor{blue}{Step:4}]{$C(G \setminus \mathbf{X}) = \{S_1, \ldots, S_{k}\}$}
	\STATE \textbf{Return} $\sum_{\mathbf{v\setminus  (y \cup x)} } \prod_i ID(s_i, \mathbf{v}\setminus s_i, P, G)$
	\ENDIF

	\IF{$C(G \setminus \mathbf{X}) = \{S\}$}

	\IF[\textcolor{blue}{Step:5}]{$C(G) = \{G\}$}
	\STATE \textbf{Return FAIL}$(G, G \cap S)$
	\ENDIF


	\IF[\textcolor{blue}{Step:6}]{$S \in C(G)$}
	\STATE \textbf{Return} $\sum_{s\setminus \mathbf{y}}\prod_{\{i | V_{i} \in S\}} P(v_{i} | v_{\pi}^{i-1})$
	\ENDIF

	\IF[\textcolor{blue}{Step:7}]{$\exists S' $ s.t. $S\subset S'\in C(G)$}  
	\STATE \textbf{Return ID}$(\mathbf{y}, \mathbf{x}\cap S', {P}=
	\prod_{\{i | V_{i} \in S'\}}P(V_{i}| V_{\pi}^{(i-1)}\cap S', v_{\pi}^{(i-1)}\setminus S'  ), G_{S'})$
	\ENDIF
	\ENDIF
\end{algorithmic}
\label{alg:ID}


\footnotesize
\caption{\footnotesize IDC(${Y}, {X}, {Z}, P, G$) }
\begin{algorithmic}[1]


	\STATE \textbf{Input:} $x,y,z$ value assignments, $P$ a probability distribution, $G$ a causal diagram (an I-map of $P$).
	\STATE {\bfseries Output:} Expression for $P_{{X}}({Y|Z})$ in terms of $P$ or Fail(F, F').

	\IF{ $\exists \alpha \in Z$ such that $({Y} \perp \!\!\! \perp \alpha| {X}, {Z}\setminus \{\alpha\})_{G_{\overline{{X}}, \underline{\alpha}}}$}
	\STATE \textbf{return} IDC(${Y}, {X} \cup \{\alpha\}, {Z}\setminus \{\alpha\}, \mathcal{D}, G$)

	\ELSE
	\STATE let $P'$ = ID($\mathbf{y \cup z,x}, P, G$)
	\STATE return $P'/ \sum_{\mathbf{y}} P'$
	\ENDIF
\end{algorithmic}
\label{alg:IDC}
